mapper.select:
SELECT a.id AS recordId, a.inspection_batch_id AS batchId, b.batch_name AS batchName, a.user_id AS userId, u.real_name AS userName, u.phone AS userPhone, a.rule_id AS ruleId, r.rule_name AS ruleName, r.points AS ruleScore, a.source_type AS sourceType, a.inspector_id AS inspectorId, u2.real_name AS inspectorName, a.inspection_date AS inspectionDate, a.description, a.images, a.status, a.create_time AS createTime FROM points_apply a LEFT JOIN `user` u ON a.user_id = u.id LEFT JOIN points_rule r ON a.rule_id = r.id LEFT JOIN `user` u2 ON a.inspector_id = u2.id LEFT JOIN inspection_batch b ON a.inspection_batch_id = b.id
a.source_type = 'admin'
AND a.inspection_batch_id = #{query.batchId}
AND a.user_id = #{query.userId}
AND a.inspection_date >= #{query.startDate}
AND a.inspection_date <= #{query.endDate}
ORDER BY a.create_time DESC

SELECT b.batch_name AS batchName, a.inspection_date AS inspectionDate, u.real_name AS userName, r.rule_name AS ruleName, r.points AS score, u2.real_name AS inspectorName, a.description, a.create_time AS createTime FROM points_apply a LEFT JOIN `user` u ON a.user_id = u.id LEFT JOIN points_rule r ON a.rule_id = r.id LEFT JOIN `user` u2 ON a.inspector_id = u2.id LEFT JOIN inspection_batch b ON a.inspection_batch_id = b.id
a.source_type = 'admin'
AND a.inspection_batch_id = #{query.batchId}
AND a.user_id = #{query.userId}
AND a.inspection_date >= #{query.startDate}
AND a.inspection_date <= #{query.endDate}
ORDER BY a.create_time DESC
